fn on_event(event, state) {
    if state == () {
        state = #{active: false, cancelled: false, repeat_key: "", next_repeat: 0};
    }
    let actions = [];
    if event.pressed.contains("l1") {
        state.active = true;
        state.cancelled = false;
        state.repeat_key = "";
        actions.push(#{type: "key_down", key: "cmd"});
        actions.push(#{type: "key_tap", key: "Tab"});
    }
    let handled = state.active;
    if state.active && event.released.contains("l1") {
        actions.push(#{type: "release_all"});
        state.active = false;
        state.repeat_key = "";
    } else if state.active && !state.cancelled {
        if event.pressed.contains("dpad_down") {
            actions.push(#{type: "key_tap", key: "Escape"});
            actions.push(#{type: "release_all"});
            state.cancelled = true;
            state.repeat_key = "";
        } else {
            for pair in [["dpad_left", "ArrowLeft"], ["dpad_right", "ArrowRight"]] {
                if event.pressed.contains(pair[0]) {
                    actions.push(#{type: "key_tap", key: pair[1]});
                    state.repeat_key = pair[0];
                    state.next_repeat = event.time_ms + 450;
                }
            }
            if state.repeat_key != "" && !event.held.contains(state.repeat_key) {
                state.repeat_key = "";
            }
            if event.kind == "tick" && state.repeat_key != "" && event.time_ms >= state.next_repeat {
                let key = if state.repeat_key == "dpad_left" { "ArrowLeft" } else { "ArrowRight" };
                actions.push(#{type: "key_tap", key: key});
                state.next_repeat = event.time_ms + 100;
            }
        }
    }
    #{handled: handled, actions: actions, state: state}
}
